def compute(vars):
    old_revenue = vars["v1"]
    new_revenue = vars["v2"]
    change = new_revenue - old_revenue

    return {
        "value": change,
        "trace": {
            "old_revenue": old_revenue,
            "new_revenue": new_revenue,
            "change": change,
            "output_meta": {
                "currency": "GBP",
                "scale": "million",
                "unit": None
            }
        }
    }
